def parse_amount(raw: str) -> float:
    """Parse a settlement CSV amount string into a signed float."""
    cleaned = raw.strip().replace(',', '')
    if cleaned.startswith('(') and cleaned.endswith(')'):
        return -float(cleaned[1:-1])
    return float(cleaned)

