SUPPORTED = {'USD', 'EUR', 'GBP', 'JPY', 'CAD'}

def normalize_iso_currency(code: str) -> str:
    """Strip whitespace, uppercase the ISO 4217 code, and validate against SUPPORTED."""
    cleaned = code.strip().upper()
    if cleaned not in SUPPORTED:
        raise ValueError(f'Unsupported currency: {code}')
    return cleaned
